mapper.select:
/***selectJobRunHstList***/ SELECT CAST(COUNT(MAIN.exec_id) OVER() AS INTEGER) AS totcnt ,MAIN.* FROM( select A.EXEC_ID ,A.JOB_ID ,A.JOB_NM_KR ,B.JOB_NM_EN ,B.CLASS_NM ,C.JOB_TYPE ,B.RECIVE_INST ,B.RECIVE_SYS ,A.JOB_END_AT ,TO_CHAR(TO_TIMESTAMP(A.JOB_START_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS')AS JOB_START_DT ,TO_CHAR(TO_TIMESTAMP(A.JOB_END_DT,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI:SS')AS JOB_END_DT ,ROUND(CAST(CAST(A.JOB_ELAP_TIME AS FLOAT)/1000 AS NUMERIC),2) AS JOB_ELAP_TIME ,a.SEND_FILE_ID ,TO_CHAR( A.SEND_WRITE_LINE , '999,999,999,999,999') AS SEND_WRITE_LINE ,A.JOB_END_RSLT ,(SELECT A.PROCESS_ERR_CONT FROM( SELECT PROCESS_ERR_CONT ,ROW_NUMBER () OVER (PARTITION BY EXEC_ID ORDER BY PROCESS_SN DESC) FROM JOB_RUN_DETAIL_HST WHERE EXEC_ID=A.EXEC_ID )A WHERE A.ROW_NUMBER=1 ) AS PROCESS_ERR_CONT FROM JOB_RUN_HST A, JOB_MST B, JOB_LINK_CONFIG C WHERE 1=1 AND A.JOB_END_AT ='Y'
AND A.JOB_NM_KR LIKE '%' || #{jobNmKr} || '%'
AND C.JOB_TYPE = #{jobType}
AND A.JOB_END_RSLT LIKE '%' || #{jobEndRslt} || '%'
AND SUBSTR(A.JOB_END_DT,1,8) BETWEEN #{jobStartDt} AND #{jobEndDt}
AND A.JOB_ID=B.JOB_ID AND A.JOB_ID=C.JOB_ID ) MAIN ORDER BY MAIN.JOB_END_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}
